#!/usr/bin/env python3
"""Seed-level comparison: flat-NLI RSFT vs CED RSFT.

Usage:
  python seed_comparison.py                  # one-shot
  python seed_comparison.py --watch 60       # re-check every 60s
  python seed_comparison.py --json-only      # JSON output only
"""

import json, os, sys, time, argparse
from pathlib import Path
from datetime import datetime
import math

EVAL_ROOT = Path("/root/autodl-tmp/eval_results")
OUT_DIR = EVAL_ROOT

# Directory mapping: method -> {seed_label: eval_dir_name}
# For flat-NLI s43, prefer reeval over original (original had bad field compliance)
METHODS = {
    "CED_RSFT": {
        "s42": "rsft_r2b",
        "s43": "rsft_s43",
        "s44": "rsft_s44",
    },
    "flatNLI_RSFT": {
        "s42": "rsft_flat_nli",
        "s43": ["rsft_flat_nli_s43_reeval", "rsft_flat_nli_s43"],  # prefer reeval
        "s44": "rsft_flat_nli_s44",
    },
}

METRICS_KEYS = ["f1", "evi_f1", "edcr"]
METRIC_LABELS = {"f1": "rel_f1", "evi_f1": "evi_f1", "edcr": "EDCR"}


def load_metrics(eval_dir_name):
    """Load metrics.json, return dict or None if not ready."""
    if isinstance(eval_dir_name, list):
        for name in eval_dir_name:
            result = load_metrics(name)
            if result is not None:
                return result
        return None

    p = EVAL_ROOT / eval_dir_name / "metrics.json"
    if not p.exists():
        return None
    with open(p) as f:
        m = json.load(f)
    # Sanity: skip bad evals (field_compliance_rate == 0 or f1 < 0.01)
    if m.get("field_compliance_rate", 0) == 0 or m.get("f1", 0) < 0.01:
        return None
    return m


def mean(vals):
    return sum(vals) / len(vals) if vals else float("nan")


def std(vals):
    if len(vals) < 2:
        return float("nan")
    m = mean(vals)
    return math.sqrt(sum((v - m) ** 2 for v in vals) / (len(vals) - 1))


def cohens_d(a, b):
    """Cohen's d for paired samples."""
    if len(a) < 2 or len(b) < 2:
        return float("nan")
    diffs = [x - y for x, y in zip(a, b)]
    d_mean = mean(diffs)
    d_std = std(diffs)
    if d_std == 0:
        return float("inf") if d_mean != 0 else 0.0
    return d_mean / d_std


def paired_ttest(a, b):
    """Paired t-test. Returns (t_stat, p_value, n)."""
    n = len(a)
    if n < 2:
        return float("nan"), float("nan"), n
    diffs = [x - y for x, y in zip(a, b)]
    d_mean = mean(diffs)
    d_std = std(diffs)
    if d_std == 0:
        return float("inf") if d_mean != 0 else 0.0, 0.0, n
    t_stat = d_mean / (d_std / math.sqrt(n))
    # two-tailed p-value approximation (Welch–Satterthwaite for df=n-1)
    # Use scipy if available, else rough approximation
    try:
        from scipy import stats as sp_stats
        p_val = sp_stats.t.sf(abs(t_stat), df=n - 1) * 2
    except ImportError:
        # Very rough: for df>=2, |t|>4.3 => p<0.05; |t|>2.9 => p<0.1
        p_val = None  # indicate scipy not available
    return t_stat, p_val, n


def ci_95(vals):
    """95% CI for the mean."""
    n = len(vals)
    if n < 2:
        return (float("nan"), float("nan"))
    m = mean(vals)
    s = std(vals)
    # t critical value for 95% CI
    t_crit_map = {2: 12.706, 3: 4.303, 4: 3.182, 5: 2.776, 6: 2.571}
    t_crit = t_crit_map.get(n, 2.0)  # fallback
    margin = t_crit * s / math.sqrt(n)
    return (m - margin, m + margin)


def build_comparison():
    """Build comparison data structure."""
    seeds = ["s42", "s43", "s44"]
    data = {}
    for method, seed_dirs in METHODS.items():
        data[method] = {}
        for seed in seeds:
            dir_name = seed_dirs.get(seed)
            if dir_name is None:
                continue
            m = load_metrics(dir_name)
            if m is not None:
                data[method][seed] = {k: m[k] for k in METRICS_KEYS if k in m}
                data[method][seed]["_dir"] = dir_name if isinstance(dir_name, str) else dir_name[0]

    return data, seeds


def format_val(v, fmt=".4f"):
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return "—"
    return f"{v:{fmt}}"


def generate_report(data, seeds):
    """Generate markdown + JSON report."""
    lines = []
    lines.append(f"# flat-NLI vs CED RSFT: Seed-Level Comparison")
    lines.append(f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    lines.append("")

    # Status
    ced_ready = list(data.get("CED_RSFT", {}).keys())
    fnli_ready = list(data.get("flatNLI_RSFT", {}).keys())
    lines.append(f"**CED RSFT**: {len(ced_ready)}/3 seeds ({', '.join(ced_ready)})")
    lines.append(f"**flat-NLI RSFT**: {len(fnli_ready)}/3 seeds ({', '.join(fnli_ready)})")
    missing = [s for s in seeds if s not in fnli_ready]
    if missing:
        lines.append(f"**Pending**: flat-NLI {', '.join(missing)}")
    lines.append("")

    # Per-seed table
    lines.append("## Per-Seed Results")
    lines.append("")
    header = "| Seed | CED rel_f1 | fNLI rel_f1 | CED evi_f1 | fNLI evi_f1 | CED EDCR | fNLI EDCR |"
    sep    = "|------|-----------|------------|-----------|------------|---------|----------|"
    lines.append(header)
    lines.append(sep)

    for seed in seeds:
        ced = data.get("CED_RSFT", {}).get(seed, {})
        fnli = data.get("flatNLI_RSFT", {}).get(seed, {})
        row = f"| {seed} | {format_val(ced.get('f1'))} | {format_val(fnli.get('f1'))} | {format_val(ced.get('evi_f1'))} | {format_val(fnli.get('evi_f1'))} | {format_val(ced.get('edcr'))} | {format_val(fnli.get('edcr'))} |"
        lines.append(row)

    lines.append("")

    # Summary stats
    lines.append("## Summary Statistics")
    lines.append("")

    json_out = {"timestamp": datetime.now().isoformat(), "per_seed": {}, "summary": {}}

    for metric_key in METRICS_KEYS:
        label = METRIC_LABELS[metric_key]
        ced_vals = [data["CED_RSFT"][s][metric_key] for s in seeds if s in data.get("CED_RSFT", {}) and metric_key in data["CED_RSFT"].get(s, {})]
        fnli_vals = [data["flatNLI_RSFT"][s][metric_key] for s in seeds if s in data.get("flatNLI_RSFT", {}) and metric_key in data["flatNLI_RSFT"].get(s, {})]

        ced_m, ced_s = mean(ced_vals), std(ced_vals)
        fnli_m, fnli_s = mean(fnli_vals), std(fnli_vals)

        lines.append(f"**{label}**:")
        lines.append(f"  - CED:  {format_val(ced_m)} ± {format_val(ced_s)} (n={len(ced_vals)})")
        lines.append(f"  - fNLI: {format_val(fnli_m)} ± {format_val(fnli_s)} (n={len(fnli_vals)})")

        # Delta
        delta = fnli_m - ced_m if not (math.isnan(fnli_m) or math.isnan(ced_m)) else float("nan")
        lines.append(f"  - Δ (fNLI - CED): {format_val(delta, '+.4f')}")

        # Paired stats (only if matched seeds)
        matched_seeds = [s for s in seeds if s in data.get("CED_RSFT", {}) and s in data.get("flatNLI_RSFT", {}) and metric_key in data["CED_RSFT"].get(s, {}) and metric_key in data["flatNLI_RSFT"].get(s, {})]
        if len(matched_seeds) >= 2:
            a = [data["CED_RSFT"][s][metric_key] for s in matched_seeds]
            b = [data["flatNLI_RSFT"][s][metric_key] for s in matched_seeds]
            t_stat, p_val, n = paired_ttest(a, b)
            d = cohens_d(b, a)  # fNLI - CED direction
            ci_lo, ci_hi = ci_95([bv - av for av, bv in zip(a, b)])
            lines.append(f"  - Paired t-test: t={format_val(t_stat, '.3f')}, p={'N/A (no scipy)' if p_val is None else format_val(p_val, '.4f')}, n={n}")
            lines.append(f"  - Cohen's d: {format_val(d, '.3f')}")
            lines.append(f"  - 95% CI (Δ): [{format_val(ci_lo, '.4f')}, {format_val(ci_hi, '.4f')}]")
            if n < 3:
                lines.append(f"  - ⚠ N={n} < 3: stats unreliable, waiting for more seeds")
        else:
            lines.append(f"  - ⚠ Only {len(matched_seeds)} matched seed(s) — need ≥2 for paired stats")

        lines.append("")

        json_out["summary"][label] = {
            "CED_mean": ced_m, "CED_std": ced_s, "CED_n": len(ced_vals),
            "fNLI_mean": fnli_m, "fNLI_std": fnli_s, "fNLI_n": len(fnli_vals),
            "delta": delta,
        }

    # Per-seed JSON
    for seed in seeds:
        json_out["per_seed"][seed] = {}
        for method in ["CED_RSFT", "flatNLI_RSFT"]:
            if seed in data.get(method, {}):
                json_out["per_seed"][seed][method] = {
                    METRIC_LABELS[k]: v for k, v in data[method][seed].items() if k in METRICS_KEYS
                }

    json_out["status"] = {
        "CED_seeds_ready": ced_ready,
        "flatNLI_seeds_ready": fnli_ready,
        "missing": missing,
        "all_complete": len(fnli_ready) == 3 and len(ced_ready) == 3,
    }

    return "\n".join(lines), json_out


def run_once():
    data, seeds = build_comparison()
    md, js = generate_report(data, seeds)
    # Write outputs
    md_path = OUT_DIR / "seed_comparison.md"
    json_path = OUT_DIR / "seed_comparison.json"
    md_path.write_text(md)
    json_path.write_text(json.dumps(js, indent=2, ensure_ascii=False))
    return md, js


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--watch", type=int, default=0, help="Watch interval in seconds (0=one-shot)")
    parser.add_argument("--json-only", action="store_true")
    args = parser.parse_args()

    if args.watch > 0:
        print(f"[watch mode] Checking every {args.watch}s. Ctrl+C to stop.")
        prev_status = None
        while True:
            md, js = run_once()
            status = js["status"]
            if status != prev_status:
                if not args.json_only:
                    print("\n" + "=" * 60)
                    print(md)
                else:
                    print(json.dumps(js, indent=2))
                prev_status = status
                if status["all_complete"]:
                    print("\n✓ All seeds complete!")
                    break
            else:
                print(f"[{datetime.now().strftime('%H:%M:%S')}] No change. {len(status['flatNLI_seeds_ready'])}/3 flat-NLI seeds ready.")
            time.sleep(args.watch)
    else:
        md, js = run_once()
        if args.json_only:
            print(json.dumps(js, indent=2))
        else:
            print(md)
        print(f"\nWritten: {OUT_DIR}/seed_comparison.md, seed_comparison.json")


if __name__ == "__main__":
    main()
